package com.tihai.utils;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import java.nio.file.*;import java.io.*;
@Service public class AccountRegistry {
 @Autowired(required=false) private JdbcTemplate db;private final Path root;private final ObjectMapper json=new ObjectMapper();private Map<String,Map<String,Object>> accounts=new LinkedHashMap<>();private Map<String,String> selected=new LinkedHashMap<>(),owners=new LinkedHashMap<>();private String platform="chaoxing";
 public AccountRegistry(){this(com.tihai.utils.InstallRoot.path(""));}public AccountRegistry(Path p){root=p;try{Path f=p.resolve("config/platform-accounts.json");if(Files.exists(f)){Map m=json.readValue(Files.readAllBytes(f),Map.class);accounts=(Map)m.getOrDefault("accounts",accounts);selected=(Map)m.getOrDefault("selected",selected);owners=(Map)m.getOrDefault("owners",owners);platform=String.valueOf(m.getOrDefault("platform",platform));}}catch(Exception e){throw new IllegalStateException("账号配置无法读取，未覆盖原文件",e);}}
 public static String chaoxingId(String account){return UUID.nameUUIDFromBytes(("chaoxing|"+account).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 private synchronized void save()throws IOException{Map m=new LinkedHashMap();m.put("accounts",accounts);m.put("selected",selected);m.put("owners",owners);m.put("platform",platform);Path f=root.resolve("config/platform-accounts.json");Files.createDirectories(f.getParent());Path tmp=f.resolveSibling(f.getFileName()+".new");Files.write(tmp,json.writeValueAsBytes(m));try{Files.move(tmp,f,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,f,StandardCopyOption.REPLACE_EXISTING);}}
 public synchronized void refresh()throws IOException{if(db==null)return;boolean changed=false;for(Map<String,Object> r:db.queryForList("SELECT account FROM th_wk_user")){String a=String.valueOf(r.get("account")),id=chaoxingId(a);if(!accounts.containsKey(id)){registerChaoxing(a,false);changed=true;}}for(Map<String,Object> r:db.queryForList("SELECT id,login_account FROM th_wk_queue ORDER BY creat_time DESC")){String a=String.valueOf(r.get("login_account")),id=chaoxingId(a);if(!accounts.containsKey(id)){registerChaoxing(a,false);changed=true;}String task=String.valueOf(r.get("id"));if(!id.equals(owners.put(task,id)))changed=true;if(!selected.containsKey("chaoxing")){selected.put("chaoxing",id);changed=true;}}if(changed)save();}
 public synchronized String registerChaoxing(String a,boolean choose)throws IOException{if(a==null||a.trim().isEmpty())throw new IOException("账号为空");String id=chaoxingId(a);if(!accounts.containsKey(id)){Map m=new LinkedHashMap();m.put("id",id);m.put("platform","chaoxing");m.put("account",a);m.put("label",mask(a));m.put("verified",true);accounts.put(id,m);}if(choose){selected.put("chaoxing",id);platform="chaoxing";}save();return id;}
 public synchronized Map<String,Object> addRain(String label,String entry)throws IOException{if(label==null||label.trim().isEmpty()||label.length()>60)throw new IOException("请输入账号名称（1至60字）");String url=RainStore.validate(entry,false);String id=UUID.randomUUID().toString();Map m=new LinkedHashMap();m.put("id",id);m.put("platform","yuketang");m.put("account",id);m.put("label",label.trim());m.put("entry",url);m.put("verified",false);accounts.put(id,m);selected.put("yuketang",id);platform="yuketang";save();return new LinkedHashMap<>(m);}
 public synchronized void verified(String id,String identity)throws IOException{Map a=lookup(id);if(!"yuketang".equals(a.get("platform")))throw new IOException("平台不匹配");if(identity==null||identity.trim().isEmpty())throw new IOException("未读取到登录身份");for(Map other:accounts.values())if(!id.equals(other.get("id"))&&identity.equals(other.get("identity"))&&Objects.equals(other.get("entry"),a.get("entry")))throw new IOException("该雨课堂账号已存在，请切换已有账号");accounts.get(id).put("verified",true);accounts.get(id).put("identity",identity);save();}
 public synchronized Map<String,Object> lookup(String id){Map<String,Object> a=accounts.get(id);if(a==null)throw new IllegalArgumentException("账号不存在，请刷新账号列表");return new LinkedHashMap<>(a);}
 public synchronized Map<String,Object> resolve(String p,String id){if(!Arrays.asList("chaoxing","yuketang").contains(p))throw new IllegalArgumentException("平台无效");String chosen=id==null||id.isEmpty()?selected.get(p):id;if(chosen==null){Map m=new LinkedHashMap();m.put("id","");m.put("platform",p);m.put("account","__no_account__");return m;}Map a=lookup(chosen);if(!p.equals(a.get("platform")))throw new IllegalArgumentException("账号与平台不匹配");return a;}
 public synchronized void select(String p,String id)throws IOException{Map a=resolve(p,id);if(!String.valueOf(a.get("id")).isEmpty())selected.put(p,String.valueOf(a.get("id")));platform=p;save();}
 public synchronized String platform(){return platform;}public synchronized List<Map<String,Object>> allChaoxing(){List<Map<String,Object>> out=new ArrayList<>();for(Map a:accounts.values())if("chaoxing".equals(a.get("platform")))out.add(new LinkedHashMap<>(a));return out;}
 public synchronized void resource(String kind,String id,String account)throws IOException{String key=kind+":"+id,owner=chaoxingId(account);if(!owner.equals(owners.get(key))){owners.put(key,owner);save();}}
 public synchronized boolean ownsResource(String kind,String id){return !AccountScope.scoped()||AccountScope.id().equals(owners.get(kind+":"+id));}
 public synchronized void requireResource(String kind,String id){if(!ownsResource(kind,id))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"条目不属于当前账号，请刷新列表");}
 public synchronized void attachTask(String task,String accountId)throws IOException{lookup(accountId);if(!accountId.equals(owners.put(task,accountId)))save();}public synchronized boolean ownsTask(String task){return !AccountScope.scoped()||AccountScope.id().equals(owners.get(task));}public synchronized void requireTask(String task){if(!ownsTask(task))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"任务或复习资料不属于当前账号");}
 public synchronized Map<String,Object> view()throws IOException{refresh();List<Map<String,Object>> out=new ArrayList<>();for(Map a:accounts.values()){Map m=new LinkedHashMap(a);m.remove("account");m.remove("identity");out.add(m);}Map m=new LinkedHashMap();m.put("accounts",out);m.put("selected",new LinkedHashMap<>(selected));m.put("platform",platform);return m;}
 static String mask(String a){return a.length()<7?a:a.substring(0,3)+"****"+a.substring(a.length()-4);}
}

